#include "rea/semantic_ir.hpp"
#include <iostream>
#include <stdexcept>
using namespace rea;
void check(bool b){if(!b)throw std::runtime_error("semantic assertion");}
SemanticResult recover(std::initializer_list<uint8_t> bytes){std::vector<uint8_t> b(bytes);std::vector<Instruction> code;X86InstructionDecoder d;for(size_t p=0;p<b.size();){auto i=d.decode(std::span(b).subspan(p),0x5000+p,p);check(i.size);p+=i.size;code.push_back(i);}AnalysisControl c;auto f=X86IRLifter{}.function(0x5000,code,c);return recoverIntegerFunction(f,c);}
int main(){try{
 auto sum=recover({0x55,0x48,0x89,0xe5,0x89,0x7d,0xfc,0x89,0x75,0xf8,0x8b,0x45,0xfc,0x03,0x45,0xf8,0x5d,0xc3});check(sum.recovered);for(uint64_t a:{0ULL,1ULL,0x7fffffffULL,0xffffffffULL})for(uint64_t b:{0ULL,2ULL,0x80000000ULL,0xffffffffULL})check(sum.evaluate({a,b})==uint32_t(a+b));
 auto partial=recover({0xb8,0x78,0x56,0x34,0x12,0xb4,0xab,0xb0,0xcd,0xc3});check(partial.recovered && partial.evaluate({})==0x1234abcd);
 auto endian=recover({0x55,0x48,0x89,0xe5,0xc7,0x45,0xfc,0x78,0x56,0x34,0x12,0x8a,0x45,0xfd,0xb4,0,0x66,0x25,0xff,0,0x0f,0xb7,0xc0,0x5d,0xc3});check(!endian.recovered); // MOVZX is explicitly unsupported.
 auto bytes=recover({0x55,0x48,0x89,0xe5,0xb8,0,0,0,0,0xc7,0x45,0xfc,0x78,0x56,0x34,0x12,0x8a,0x45,0xfd,0x5d,0xc3});check(bytes.recovered && bytes.evaluate({})==0x56);
 auto wrap=recover({0xb8,0xff,0xff,0xff,0xff,0x83,0xc0,1,0xc3});check(wrap.recovered && wrap.evaluate({})==0);
 auto zeroextend=recover({0x48,0xb8,0xff,0xff,0xff,0xff,0xff,0xff,0xff,0xff,0xb8,1,0,0,0,0x48,0x89,0xc2,0x89,0xd0,0xc3});check(zeroextend.recovered && zeroextend.evaluate({})==1);
 check(!recover({0x89,0x07,0xc3}).recovered);check(!recover({0x75,0,0xc3}).recovered);check(!recover({0x55,0xc3}).recovered);check(!recover({0x0f,0x05,0xc3}).recovered);
 auto sixth=recover({0x44,0x89,0xc8,0x83,0xe8,1,0xc3});check(sixth.recovered && sixth.evaluate({0,0,0,0,0,42})==41);
 std::cout<<sum.code<<"PASS stack/partial registers/little endian/bitvectors/ABI/conservative rejection\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
